INSERT INTO `notices` (`title`,`body`,`is_pinned`,`created_at`,`updated_at`) SELECT '사업자 인증 안내: 가입 후 영업일 기준 1일 이내 승인','<p>오프라인 매장, 온라인 판매, 판매 네트워크 중 하나만 증빙하면 됩니다. 매장 사진, 판매 글 캡처, 거래처 대화 캡처 등 사진·캡처도 인정하며, 담당자가 직접 확인한 뒤 승인합니다.</p><p>승인 전에는 상품은 보실 수 있지만 도매가와 주문 신청은 제한됩니다.</p>',1,NOW(),NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `notices` WHERE `title`='사업자 인증 안내: 가입 후 영업일 기준 1일 이내 승인');
INSERT INTO `notices` (`title`,`body`,`is_pinned`,`created_at`,`updated_at`) SELECT '결제 안내: 주문 신청 후 KBZPay 선불','<p>주문 신청 → 담당자가 배송비 포함 최종 금액 안내 → KBZPay 송금 → 입금 캡처 업로드 → 입금 확인 후 발주·배송.</p>',1,NOW(),NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `notices` WHERE `title`='결제 안내: 주문 신청 후 KBZPay 선불');
INSERT INTO `notices` (`title`,`body`,`is_pinned`,`created_at`,`updated_at`) SELECT '친구 소개 포인트 안내','<p>마이페이지의 추천 코드를 공유하세요. 소개한 회원이 승인되면 포인트가 적립되고, 그 회원이 첫 주문을 하면 추가 적립됩니다.</p>',0,NOW(),NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `notices` WHERE `title`='친구 소개 포인트 안내');
